import asyncio, sys
async def run_tasks(tasks, mc):
    sem=asyncio.Semaphore(mc)
    async def _run_one(m):
        async with sem: await m()
    running=[asyncio.ensure_future(_run_one(t)) for t in tasks]
    try:
        await asyncio.gather(*running)
    except BaseException:
        cur=asyncio.current_task()
        while cur.cancelling()>0: cur.uncancel()
        for f in running:
            if not f.done(): f.cancel()
        waiter=asyncio.ensure_future(asyncio.gather(*running, return_exceptions=True))
        i=0
        while not waiter.done():
            i+=1
            try:
                await asyncio.shield(waiter)
            except (asyncio.CancelledError, KeyboardInterrupt):
                while cur.cancelling()>0: cur.uncancel()
        print('waiter loops:', i, 'waiter.done:', waiter.done(), file=sys.stderr)
        raise
async def test(n,mc):
    cleaned=[]
    def make(i):
        async def task():
            try: await asyncio.sleep(10)
            except asyncio.CancelledError:
                await asyncio.sleep(0.01); cleaned.append(i); raise
        return task
    r=asyncio.ensure_future(run_tasks([make(i) for i in range(n)],mc))
    await asyncio.sleep(0.1)
    r.cancel()
    try: await r
    except asyncio.CancelledError: pass
    print(f'n={n} mc={mc} cleaned:', sorted(cleaned))
asyncio.run(test(5,3))
"

